//! The local marks' markets (design 000454): which venues list each HL main-dex coin, under which symbol, at which
//! price multiplier. `server/data/mark_sources.json` is generated by `scripts/discover_mark_sources.py` from the
//! venues' public listings, each checked against HL's own price, and embedded at build time: a build subscribes to
//! exactly the reviewed markets. HYPE and PURR (USDC-quoted perps) and HIP-3 are not in it.

use std::collections::BTreeMap;

use rustc_hash::FxHashMap;
use serde::Deserialize;

use super::price::VenuePrice;

const EMBEDDED: &str = include_str!("../../data/mark_sources.json");

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub(crate) enum Venue {
    Binance,
    Okx,
    Bybit,
    Kraken,
    Kucoin,
    Gate,
    Mexc,
}

impl Venue {
    const ALL: [Self; 7] = [Self::Binance, Self::Okx, Self::Bybit, Self::Kraken, Self::Kucoin, Self::Gate, Self::Mexc];

    pub(crate) const fn name(self) -> &'static str {
        match self {
            Self::Binance => "binance",
            Self::Okx => "okx",
            Self::Bybit => "bybit",
            Self::Kraken => "kraken",
            Self::Kucoin => "kucoin",
            Self::Gate => "gate",
            Self::Mexc => "mexc",
        }
    }

    fn parse(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|venue| venue.name() == name)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub(crate) enum Kind {
    /// Prices the oracle.
    Spot,
    /// Prices the external perp price.
    Perp,
}

/// One venue's markets of one kind: one WS connection or one poll.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub(crate) struct Feed {
    pub(crate) kind: Kind,
    pub(crate) venue: Venue,
}

impl Feed {
    /// The venues of each kind: seven spot venues price the oracle, five perp venues the external price.
    pub(crate) const ALL: [Self; 12] = [
        Self::spot(Venue::Binance),
        Self::spot(Venue::Okx),
        Self::spot(Venue::Bybit),
        Self::spot(Venue::Kraken),
        Self::spot(Venue::Kucoin),
        Self::spot(Venue::Gate),
        Self::spot(Venue::Mexc),
        Self::perp(Venue::Binance),
        Self::perp(Venue::Okx),
        Self::perp(Venue::Bybit),
        Self::perp(Venue::Gate),
        Self::perp(Venue::Mexc),
    ];

    const fn spot(venue: Venue) -> Self {
        Self { kind: Kind::Spot, venue }
    }

    const fn perp(venue: Venue) -> Self {
        Self { kind: Kind::Perp, venue }
    }

    /// The venue's weight in its median (the service's, after HL's published oracle weights): Binance 3, OKX 2,
    /// Bybit 2, every other 1.
    pub(crate) const fn weight(self) -> u32 {
        match self.venue {
            Venue::Binance => 3,
            Venue::Okx | Venue::Bybit => 2,
            Venue::Kraken | Venue::Kucoin | Venue::Gate | Venue::Mexc => 1,
        }
    }

    /// `spot_binance`, `perp_okx`, ...: the metrics' and logs' label.
    pub(crate) fn label(self) -> &'static str {
        match (self.kind, self.venue) {
            (Kind::Spot, Venue::Binance) => "spot_binance",
            (Kind::Spot, Venue::Okx) => "spot_okx",
            (Kind::Spot, Venue::Bybit) => "spot_bybit",
            (Kind::Spot, Venue::Kraken) => "spot_kraken",
            (Kind::Spot, Venue::Kucoin) => "spot_kucoin",
            (Kind::Spot, Venue::Gate) => "spot_gate",
            (Kind::Spot, Venue::Mexc) => "spot_mexc",
            (Kind::Perp, Venue::Binance) => "perp_binance",
            (Kind::Perp, Venue::Okx) => "perp_okx",
            (Kind::Perp, Venue::Bybit) => "perp_bybit",
            (Kind::Perp, Venue::Gate) => "perp_gate",
            (Kind::Perp, Venue::Mexc) => "perp_mexc",
            (Kind::Perp, Venue::Kraken | Venue::Kucoin) => unreachable!("Kraken and Kucoin are no perp feed (`Feed::ALL`)"),
        }
    }

    fn of(kind: Kind, name: &str) -> Option<Self> {
        let feed = Self { kind, venue: Venue::parse(name)? };
        Self::ALL.contains(&feed).then_some(feed)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Listing {
    pub(crate) symbol: String,
    /// HL price = multiplier × venue price.
    pub(crate) px_multiplier: VenuePrice,
}

/// One feed's markets, in coin order: its symbols, and each one's coin and multiplier.
#[derive(Debug, Default)]
pub(crate) struct FeedMarkets {
    pub(crate) symbols: Vec<String>,
    pub(crate) coins: Vec<(String, VenuePrice)>,
    by_symbol: FxHashMap<String, usize>,
}

impl FeedMarkets {
    /// The symbol's place in `symbols`; `None` for a market this build does not subscribe to.
    pub(crate) fn index(&self, symbol: &str) -> Option<usize> {
        self.by_symbol.get(symbol).copied()
    }
}

/// Every coin's listings and every feed's markets.
#[derive(Debug)]
pub(crate) struct MarkSources {
    coins: BTreeMap<String, BTreeMap<Feed, Listing>>,
    feeds: BTreeMap<Feed, FeedMarkets>,
}

#[derive(Deserialize)]
struct SourcesFile {
    coins: BTreeMap<String, CoinEntry>,
}

#[derive(Deserialize)]
struct CoinEntry {
    spot: BTreeMap<String, ListingEntry>,
    perp: BTreeMap<String, ListingEntry>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ListingEntry {
    symbol: String,
    px_multiplier: String,
}

impl MarkSources {
    /// The sources this build embeds.
    pub(crate) fn embedded() -> Result<Self, String> {
        Self::parse(EMBEDDED)
    }

    /// Every coin needs a spot listing (its oracle) and a perp listing (its external price, design 000454 r2
    /// revision 2); a feed lists a symbol once; venues and multipliers are checked.
    pub(crate) fn parse(text: &str) -> Result<Self, String> {
        let file: SourcesFile = serde_json::from_str(text).map_err(|err| format!("mark sources: {err}"))?;
        let mut coins = BTreeMap::new();
        let mut feeds: BTreeMap<Feed, FeedMarkets> = BTreeMap::new();
        for (coin, entry) in file.coins {
            if entry.spot.is_empty() || entry.perp.is_empty() {
                return Err(format!("mark sources: {coin} needs a spot and a perp listing"));
            }
            let mut listings = BTreeMap::new();
            for (kind, entries) in [(Kind::Spot, entry.spot), (Kind::Perp, entry.perp)] {
                for (name, listing) in entries {
                    let feed = Feed::of(kind, &name).ok_or_else(|| format!("mark sources: {coin}: unknown {kind:?} venue {name}"))?;
                    let multiplier = VenuePrice::parse(&listing.px_multiplier).map_err(|err| format!("mark sources: {coin} {name}: {err}"))?;
                    if listing.symbol.is_empty() || !multiplier.is_positive() {
                        return Err(format!("mark sources: {coin}: invalid {} listing {:?} × {multiplier}", feed.label(), listing.symbol));
                    }
                    let markets = feeds.entry(feed).or_default();
                    if let Some(previous) = markets.by_symbol.insert(listing.symbol.clone(), markets.symbols.len()) {
                        return Err(format!("mark sources: {} symbol {} listed for {} and {coin}", feed.label(), listing.symbol, markets.coins[previous].0));
                    }
                    markets.symbols.push(listing.symbol.clone());
                    markets.coins.push((coin.clone(), multiplier));
                    listings.insert(feed, Listing { symbol: listing.symbol, px_multiplier: multiplier });
                }
            }
            coins.insert(coin, listings);
        }
        if coins.is_empty() {
            return Err("mark sources list no coin".to_string());
        }
        Ok(Self { coins, feeds })
    }

    pub(crate) fn coins(&self) -> impl Iterator<Item = &str> {
        self.coins.keys().map(String::as_str)
    }

    /// The coin's listings by feed; `None` for a coin outside the sources.
    pub(crate) fn listings(&self, coin: &str) -> Option<&BTreeMap<Feed, Listing>> {
        self.coins.get(coin)
    }

    /// The feeds with markets, and theirs.
    pub(crate) fn feeds(&self) -> impl Iterator<Item = (Feed, &FeedMarkets)> {
        self.feeds.iter().map(|(feed, markets)| (*feed, markets))
    }

    pub(crate) fn markets(&self, feed: Feed) -> Option<&FeedMarkets> {
        self.feeds.get(&feed)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn one(spot: &str, perp: &str) -> String {
        format!(r#"{{"coins": {{"SOL": {{"spot": {spot}, "perp": {perp}}}}}}}"#)
    }

    const SOL_SPOT: &str = r#"{"binance": {"symbol": "SOLUSDT", "pxMultiplier": "1"}}"#;
    const SOL_PERP: &str = r#"{"okx": {"symbol": "SOL-USDT-SWAP", "pxMultiplier": "1"}}"#;

    #[test]
    fn sources_are_checked_when_loaded() {
        let sources = MarkSources::parse(&one(SOL_SPOT, SOL_PERP)).unwrap();
        assert_eq!(sources.coins().collect::<Vec<_>>(), ["SOL"]);
        let okx = sources.markets(Feed::perp(Venue::Okx)).unwrap();
        assert_eq!((okx.index("SOL-USDT-SWAP"), okx.index("BTC-USDT-SWAP")), (Some(0), None));
        let cases = [
            (one(r#"{"ftx": {"symbol": "SOLUSDT", "pxMultiplier": "1"}}"#, SOL_PERP), "unknown Spot venue ftx"),
            (one(SOL_SPOT, r#"{"kraken": {"symbol": "SOL/USDT", "pxMultiplier": "1"}}"#), "unknown Perp venue kraken"),
            (one(r#"{"binance": {"symbol": "SOLUSDT", "pxMultiplier": "0"}}"#, SOL_PERP), "invalid spot_binance listing"),
            (one(SOL_SPOT, "{}"), "needs a spot and a perp listing"),
            (one("{}", SOL_PERP), "needs a spot and a perp listing"),
        ];
        for (text, message) in cases {
            let error = MarkSources::parse(&text).unwrap_err();
            assert!(error.contains(message), "{error}");
        }
        let twice = format!(r#"{{"coins": {{"SOL": {{"spot": {SOL_SPOT}, "perp": {SOL_PERP}}}, "SOL2": {{"spot": {SOL_SPOT}, "perp": {{}}}}}}}}"#);
        assert!(MarkSources::parse(&twice).is_err());
    }

    #[test]
    fn the_embedded_sources_price_every_coin_in_hl_units() {
        let sources = MarkSources::embedded().unwrap();
        let coins: Vec<&str> = sources.coins().collect();
        assert!(["BTC", "ETH", "SOL", "XRP", "ZEC", "kPEPE"].iter().all(|coin| coins.contains(coin)));
        assert!(!coins.contains(&"HYPE") && !coins.contains(&"PURR"), "USDC-quoted perps are left for later");
        let pepe = sources.listings("kPEPE").unwrap();
        assert_eq!(pepe[&Feed::spot(Venue::Binance)], Listing { symbol: "PEPEUSDT".to_string(), px_multiplier: VenuePrice::parse("1000").unwrap() });
        assert_eq!(pepe[&Feed::perp(Venue::Binance)].symbol, "1000PEPEUSDT");
        // Bybit has no ZEC spot since 2025-02-28 and Kraken no ZEC/USDT
        let zec = sources.listings("ZEC").unwrap();
        assert!(!zec.contains_key(&Feed::spot(Venue::Bybit)) && !zec.contains_key(&Feed::spot(Venue::Kraken)));
    }
}
